sealed interface Message {
    data class OrderCreated(val order: Order) : Message
    data class InvoiceIssued(val invoice: Invoice) : Message
}

fun route(msg: Message) = when (msg) {          // exhaustive: no else required
    is Message.OrderCreated  -> orders.send(msg.order)
    is Message.InvoiceIssued -> invoices.send(msg.invoice)
}
